#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/spi.h>
#include <zephyr/drivers/uart.h>
#include <zephyr/ztest.h>

#define MAX_TEST_DEVICES 10

static const struct device *init_order[MAX_TEST_DEVICES];
static int init_idx;

static int device_init(const struct device *dev)
{
    if (init_idx < ARRAY_SIZE(init_order)) {
        init_order[init_idx++] = dev;
    }
    return 0;
}

/*
 * Test devices and their dummy APIs/initialization functions.
 * These are minimal to just record initialization.
 */

/* GPIO Test Device */
static int test_gpio_init(const struct device *dev)
{
    printk("Initializing %s\n", dev->name);
    return device_init(dev);
}

static const struct gpio_driver_api test_gpio_api = {
    .pin_configure = NULL,
    .port_get_raw = NULL,
    .port_set_raw = NULL,
    .port_set_bits_raw = NULL,
    .port_clear_bits_raw = NULL,
    .port_toggle_bits = NULL,
    .pin_interrupt_configure = NULL,
    .get_pending_int = NULL,
};

DEVICE_DT_DEFINE(DT_NODELABEL(test_gpio), test_gpio_init, NULL, NULL, NULL,
                 POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT - 3, &test_gpio_api);

/* I2C Test Device */
static int test_i2c_init(const struct device *dev)
{
    printk("Initializing %s\n", dev->name);
    return device_init(dev);
}

static const struct i2c_driver_api test_i2c_api = {
    .configure = NULL,
    .transfer = NULL,
    .get_config = NULL,
};

DEVICE_DT_DEFINE(DT_NODELABEL(test_i2c), test_i2c_init, NULL, NULL, NULL,
                 POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT - 2, &test_i2c_api);

/* SPI Test Device */
static int test_spi_init(const struct device *dev)
{
    printk("Initializing %s\n", dev->name);
    return device_init(dev);
}

static const struct spi_driver_api test_spi_api = {
    .transceive = NULL,
    .release = NULL,
};

DEVICE_DT_DEFINE(DT_NODELABEL(test_spi), test_spi_init, NULL, NULL, NULL,
                 POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT - 1, &test_spi_api);

/* UART Test Device */
static int test_uart_init(const struct device *dev)
{
    printk("Initializing %s\n", dev->name);
    return device_init(dev);
}

static const struct uart_driver_api test_uart_api = {
    .poll_in = NULL,
    .poll_out = NULL,
    .err_check = NULL,
};

DEVICE_DT_DEFINE(DT_NODELABEL(test_uart), test_uart_init, NULL, NULL, NULL,
                 POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT, &test_uart_api);

/*
 * Test cases
 */

ZTEST_SUITE(devicetree_devices, NULL, NULL, NULL, NULL, NULL);

/* Test that DT_DEVICE_GET_OR_NULL works */
ZTEST(devicetree_devices, test_get_or_null)
{
    const struct device *dev;

    dev = DEVICE_DT_GET_OR_NULL(DT_NODELABEL(test_gpio));
    zassert_not_null(dev, "test_gpio device not found");

    dev = DEVICE_DT_GET_OR_NULL(DT_NODELABEL(non_existent_device));
    zassert_is_null(dev, "non_existent_device should be NULL");
}

/* Test that DT_DEVICE_GET works and devices are initialized */
ZTEST(devicetree_devices, test_init_get)
{
    const struct device *dev;

    dev = DEVICE_DT_GET(DT_NODELABEL(test_gpio));
    zassert_not_null(dev, "test_gpio device not found");
    zassert_equal(dev, init_order[0], "test_gpio not initialized first");

    dev = DEVICE_DT_GET(DT_NODELABEL(test_i2c));
    zassert_not_null(dev, "test_i2c device not found");
    zassert_equal(dev, init_order[1], "test_i2c not initialized second");

    dev = DEVICE_DT_GET(DT_NODELABEL(test_spi));
    zassert_not_null(dev, "test_spi device not found");
    zassert_equal(dev, init_order[2], "test_spi not initialized third");

    dev = DEVICE_DT_GET(DT_NODELABEL(test_uart));
    zassert_not_null(dev, "test_uart device not found");
    zassert_equal(dev, init_order[3], "test_uart not initialized fourth");
}

/* Test the initialization order of devices */
ZTEST(devicetree_devices, test_init_order)
{
    zassert_equal(init_order[0], DEVICE_DT_GET(DT_NODELABEL(test_gpio)),
                  "init_order[0] not equal to DEV_HDL(test_gpio)");
    zassert_equal(init_order[1], DEVICE_DT_GET(DT_NODELABEL(test_i2c)),
                  "init_order[1] not equal to DEV_HDL(test_i2c)");
    zassert_equal(init_order[2], DEVICE_DT_GET(DT_NODELABEL(test_spi)),
                  "init_order[2] not equal to DEV_HDL(test_spi)");
    zassert_equal(init_order[3], DEVICE_DT_GET(DT_NODELABEL(test_uart)),
                  "init_order[3] not equal to DEV_HDL(test_uart)");
    zassert_equal(init_idx, 4, "Expected 4 devices to be initialized");
}
